Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope bv_scope.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := AsanUbsan.M.loaded_segments.

Definition PATV : Z := ltac2:(Rpl.RP.run_k (rplG ()) 0 "U0;A1;o0;Y63;75f5f5f5f5f5f5f5;").

Section FPX_1. Context {fx : PropExec.FPState}.

#[local] Ltac rwH :=
  repeat match goal with
         | H : getr ?rg ?i = _ |- context [getr ?rg ?i] => rewrite !H
         end.
#[local] Ltac unorm :=
  repeat match goal with
         | |- context [bv_unsigned (Z_to_bv 64 ?z)] =>
             lazymatch z with context [Z_to_bv 64 _] => fail | _ => rewrite (u_Z2bv z) by lia end
         end.
#[local] Ltac wv2 := gres; rwH; unfold at_, v_addi, v_add, v_sub, v_srli, v_slli; imm_norm; unorm; rewrite ?Z.shiftr_div_pow2, ?Z.shiftl_mul_pow2 by lia;
  first [reflexivity | f_equal; lia].

#[local] Ltac stepsdq F D aa vv oktac :=
  chain_step; [reflexivity
    | eapply step_sd_at with (a := aa) (v := vv); [exact F | reflexivity | exact D | wv2 | gres; rwH; first [reflexivity | f_equal; lia] | oktac]
    | step_simpl].

Section SF5.
  Variable M0 : word -> option byte.
  Variable rom : word -> option byte.
  Variables sp ra : word.
  Variables s F fl sh : Z.
  Variable patv : Z.
  #[local] Abbreviation PAT := (word_to_le_bytes 8 (Z_to_bv 64 patv)).
  Hypothesis Hs_def : bv_unsigned sp = s.
  Hypothesis Hret : ret_ok ra.
  Hypothesis Hs : (0x1000000 <= s - 16)%Z /\ (s < 2 ^ 64)%Z.
  Hypothesis Hok : store_ok ASEGS M0 (Z_to_bv 64 (s - 16)) 16%nat = true.
  Hypothesis HG : rt_layout_globs M0.
  Hypothesis Happ : in_app F.
  Hypothesis HF : (0x6b4000 <= F)%Z /\ (F + 2048 <= s - 16 \/ s <= F)%Z.
  Hypothesis Hsh_def : sh = (SB + F / 8)%Z.
  Hypothesis Hfp : rdn ASEGS M0 (Z_to_bv 64 (F + 2040)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 fl)).
  Hypothesis Hfl : (0x6b4000 <= fl)%Z /\ (fl + 1 < 2 ^ 64)%Z /\ (fl + 1 <= s - 16 \/ s <= fl)%Z.
  Hypothesis Hflok : store_ok ASEGS M0 (Z_to_bv 64 fl) 1%nat = true.
  Hypothesis Hshok : store_ok ASEGS M0 (Z_to_bv 64 sh) 256%nat = true.
  Hypothesis Hshdj : (sh + 256 <= s - 16 \/ s <= sh)%Z.

  Hypothesis Hpat : forall M', (forall x : word, (bv_unsigned x < 0x6b4000)%Z -> M' x = M0 x) -> rdn ASEGS M' (0x103a8 : word) 8%nat = Some PAT.

  Definition sf5_M1 (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S2;A1;o2;Y6;00;Y3;0;Lrg;RA2;k1;A1;o2;Y2;1;A1;i3;#0;A3;k4;vM0;A2;k5;#0;A2;k6;vs;A1;o0;#1;A2;k7;N8;vra;").
  Definition sf5_M2 (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S5;A1;o2;Y2;1;A1;o2;Y6;00;Y4;0;Y3;0;A1;o0;#3;Lrg;RA2;k1;#0;A1;i3;#1;A3;k4;A1;k8;r1;A2;k5;#1;A2;k6;vs;A1;o0;#2;A2;k7;N8;A2;k9;r1;A3;o10;#0;#4;cvo11;A2;k12;#0;#4;").
  Definition sf5_M3 (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S4;A1;o2;Y6;00;Y3;0;A1;o2;#1;A1;i3;#2;Lrg;RA2;k1;A1;o2;Y2;1;A1;i3;#0;A3;k4;A1;k13;r1;A2;k5;#0;vfl;A3;o14;#3;A2;k5;#2;o15;A1;o16;#3;").
  Definition sf5_mem (rg : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S19;Y2;1;Y6;00;A1;o2;#1;A1;i3;#2;Y3;0;A2;k7;N8;A2;k5;#2;vpatv;Y4;0;Y4;8;Y5;00;Y5;08;Y5;10;Y5;18;Y6;08;Y6;10;Y6;18;Y6;20;Y6;28;Y6;30;Y6;38;Lrg;RA2;k1;A1;o2;#0;#3;EM3;RA1;k17;r1;P~R#3;A1;i18;A1;i3;A1;o2;#4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;A3;k4;r1;A2;k5;#2;vsh;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#4;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#6;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#7;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#8;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#9;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#10;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#11;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#1;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#12;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#13;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#14;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#15;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#16;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#17;#5;A2;k5;#2;A2;k19;vsh;A1;o0;#18;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;00;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;08;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;10;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;18;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;20;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;28;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;30;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;38;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;40;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;48;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;50;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;58;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;60;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;68;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;70;#5;A2;k5;#2;A2;k19;vsh;A1;o0;Y7;78;#5;").

  Lemma sp_sf5 : sp = Z_to_bv 64 s.  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S3;A1;o2;Y6;00;A2;k22;#0;vsp;A1;i3;#0;A6;k20;i21;#1;Ls;Ri21;A3;i23;#2;vsp;A2;k5;#0;r1;A4;k24;#2;A2;k5;#0;#1;vsp;A2;k25;#0;vsp;vs;vHs_def;").
Qed.

  Theorem sfree5_run : forall regs,
    getr regs 10 = Z_to_bv 64 F -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs',
